{"command": "cat > /etc/nb/routes.sh <<'EOF'
#!/bin/sh
ip route replace 172.16.0.0/12 via 10.1.0.254 dev eth4
ip route replace 10.50.0.0/16 via 10.1.0.254 dev eth4
EOF
chmod +x /etc/nb/routes.sh; sh /etc/nb/routes.sh; ip route | grep 10.1.0.254; fw-commit"}

